//! Block texture atlas layout. The constants, the alias lookup and the
//! opacity table are generated by `build.rs` from `assets/blocks/textures.json`.

include!(concat!(env!("OUT_DIR"), "/texture_layout_generated.rs"));

/// UV corners `(min, max)` of the drawable part of a tile, excluding the
/// border of repeated edge pixels around it.
pub fn tile_uv_rect(tile: usize) -> ([f32; 2], [f32; 2]) {
    let columns = ATLAS_COLUMNS as usize;
    let atlas = ATLAS_SIZE as f32;
    let left = ((tile % columns) as u32 * CELL_SIZE + TILE_GUTTER) as f32;
    let top = ((tile / columns) as u32 * CELL_SIZE + TILE_GUTTER) as f32;
    (
        [left / atlas, top / atlas],
        [
            (left + TILE_SIZE as f32) / atlas,
            (top + TILE_SIZE as f32) / atlas,
        ],
    )
}
